// Baselined allow-list - replace with your Phase 1 values
const ALLOW_IPS = ['192.168.29.X'];
const ALLOW_FCS = [3, 4, 6];

const srcIp = msg.req && msg.req.connection ? msg.req.connection.remoteAddress : msg._session.remoteAddress;
const fc = msg.payload[7]; // byte 7 of MBAP header = function code

if (!ALLOW_IPS.includes(srcIp)) {
    node.warn(`REJECTED - unauthorized source ${srcIp} (FC${fc})`);
    return null;
}
if (!ALLOW_FCS.includes(fc)) {
    node.warn(`REJECTED - disallowed function code FC${fc} from ${srcIp}`);
    return null;
}
node.log(`ALLOWED - ${srcIp} FC${fc}`);
return msg;
